arguments.command:
cd /dateutil && python - <<'EOF'
import marshal, re, glob, os
for f in sorted(glob.glob('dateutil/test/__pycache__/*.pyc')):
    data=open(f,'rb').read()
    try:
        code=marshal.loads(data[12:])
    except Exception as e:
        print(f, "ERR", e); continue
    names=set()
    def walk(c):
        for const in c.co_consts:
            if hasattr(const,'co_name'):
                if const.co_name.startswith('test'):
                    names.add(const.co_name)
                walk(const)
    walk(code)
    base=os.path.basename(f).split('.')[0]
    src='dateutil/test/%s.py'%base
    if os.path.exists(src):
        srcnames=set(re.findall(r'def (test\w+)', open(src).read()))
        d1=names-srcnames; d2=srcnames-names
        if d1 or d2:
            print(f, "pyc-only:", sorted(d1), "py-only:", sorted(d2))
print("done")
EOF
